-555d-40ba-9d8b-dbdd20b636c7", "type": "subtopic", "title": "Fairness and accountability", "children": [{"id": "a9843166-c196-4be2-9c63-c9ac24ba076e", "type": "concept", "title": "Corroboration"}, {"id": "02b943e0-30e4-4e52-a229-df107bce2112", "type": "concept", "title": "Right of reply"}, {"id": "763393cc-39c5-4022-b532-e89f9757d61c", "type": "concept", "title": "Sensitive detail"}, {"id": "1d94742b-99f0-4a86-a711-cd4a2b29a51c", "type": "concept", "title": "Power dynamics"}], "description": "Human-centered storytelling still requires verification and independence."}]}, {"id": "4f75e8c4-d178-42a4-8546-d8b51f85d077", "type": "topic", "title": "Long-Form and Narrative Journalism Projects", "description": "Guides students through ambitious reported stories that integrate scenes, explanation, analysis, and narrative drive.", "children": [{"id": "2f7e5300-96eb-4953-a0e8-55945367512e", "type": "subtopic", "title": "Project management", "children": [{"id": "b79c239a-43e8-4074-8d62-cc6080c0d196", "type": "concept", "title": "Reporting calendar"}, {"id": "e04882cd-9ce1-4687-9789-54563a2276f9", "type": "concept", "title": "Source log"}, {"id": "b4f5db23-fde8-4671-985d-170f3c17f8b5", "type": "concept", "title": "Document library"}, {"id": "13846f60-a78c-43d6-b090-0b7830008184", "type": "concept", "title": "Draft milestones"}], "description": "Long-form work requires planning, tracking, and disciplined reporting over time."}, {"id": "e974817f-a487-4970-9fc9-4d1c9e47263d", "type": "subtopic", "title": "Narrative depth", "children": [{"id": "3d357712-c4b1-4829-8023-acc7d51b0264", "type": "concept", "title": "Through-line"}, {"id": "b3bd5b7a-43b1-4483-91c3-951932bb192a", "type": "concept", "title": "Subplots"}, {"id": "f314dd4a-00dd-42e8-941a-a7703b7b388e", "type": "concept", "title": "Context chapters"}, {"id": "13819cf5-ad5e-4c56-9120-713062a5bf53", "type": "concept", "title": "Revelation sequence"}], "description": "Students integrate scenes, analysis, history, and evidence into a sustained read."}, {"id": "aacaa58f-8c67-4b61-853a-0a0d6c760475", "type": "subtopic", "title": "Reader engagement", "children": [{"id": "47d04d7c-6d40-41c8-ad54-8bb64ff3b14b", "type": "concept", "title": "Pacing"}, {"id": "6bdd9bf0-da3c-42fc-b621-dc0bd55c4c82", "type": "concept", "title": "Section hooks"}, {"id": "dc2d40ca-423a-4c2d-9d43-3d741ba42feb", "type": "concept", "title": "Compression"}, {"id": "19b1bb76-3d27-4d5b-a580-06b761c994d6", "type": "concept", "title": "Strategic summary"}], "description": "Long pieces must reward attention with momentum and clarity."}]}, {"id": "1dc4bc88-ccb6-40c4-a3f9-93d15a542cfb", "type": "topic", "title": "Fact-Checking, Ethics, and Representation", "description": "Makes accuracy, verification, fairness, consent, cultural context, and harm reduction explicit parts of feature craft.", "children": [{"id": "3a9038ca-cc8e-43ef-a4ab-eba8d20d4d8c", "type": "subtopic", "title": "Verification workflow", "children": [{"id": "52dfb05b-76ea-424d-9f23-b01391924821", "type": "concept", "title": "Source audit"}, {"id": "301da1cf-9ec0-4b95-b4b9-7df29b5a2121", "type": "concept", "title": "Quote checks"}, {"id": "dea00030-c140-4ad3-b3e7-6651f371658e", "type": "concept", "title": "Document corroboration"}, {"id": "d4599e27-8621-4419-b42d-a043bef15db1", "type": "concept", "title": "Claim-by-claim review"}], "description": "Feature writers verify names, dates, quotes, claims, chronology, and narrative details."}, {"id": "fb86ff6d-5dd6-4939-8441-928e5412a228", "type": "subtopic", "title": "Ethical storytelling", "children": [{"id": "6b1ca1a7-9427-4b12-9d20-beb7941e733a", "type": "concept", "title": "Minimizing harm"}, {"id": "32ec9d63-0d32-4c6e-88dc-9655bbf99cba", "type": "concept", "title": "Transparency"}, {"id": "bb91f062-fef7-4301-92f6-7a1cd84c1816", "type": "concept", "title": "Independence"}, {"id": "cec2c03b-ee48-4807-8bb1-1897f686d9c7", "type": "concept", "title": "Accountability"}], "description": "Students examine the responsibilities